FuncDef.Code:
// Cone - bound (approximation, not exact)
float sdConeBound(in SDFG_VEC p, in float height, in float angle)
{
    // To keep the same patameters ranges as sdCone (exact)
    angle = 0.5 * PI - angle;

    vec2 c = vec2(sin(angle), cos(angle));

    float q = length(p.xz);
    return max(dot(c.xy,vec2(q,p.y)),-height-p.y);
}
